<script setup lang="ts">
import { ref } from "vue"; import { useRouter } from "vue-router"; import { createCustomer, type CustomerInput } from "../api";
const router = useRouter(); const form = ref<CustomerInput>({ displayName: "", email: "" }); const error = ref(""); const saving = ref(false);
async function save(): Promise<void> { saving.value = true; error.value = ""; try { const customer = await createCustomer(form.value); void router.push({ name: "customers.detail.general", params: { id: customer.id } }); } catch (reason) { error.value = (reason as Error).message; } finally { saving.value = false; } }
</script>
<template><form class="entity-form" @submit.prevent="save"><header><div><p class="eyebrow">CRM</p><h1>Nuevo cliente</h1></div></header><fieldset><legend>Datos de contacto</legend><label>Nombre o razon social<input v-model="form.displayName" required /></label><label>Email<input v-model="form.email" type="email" required /></label><label>Telefono<input v-model="form.phone" /></label></fieldset><fieldset><legend>Direccion</legend><label>Direccion<input v-model="form.address" /></label><label>NIF/DNI<input v-model="form.taxId" /></label></fieldset><p v-if="error" class="feedback error">{{ error }}</p><footer><button class="secondary" type="button" @click="router.back()">Cancelar</button><button :disabled="saving">{{ saving ? "Guardando" : "Guardar cliente" }}</button></footer></form></template>